67	struct KernPair
68	{
69	  inline int get_kerning (void) const
70	  { return value; }
71	
72	  inline int cmp (const hb_glyph_pair_t &o) const
73	  {
74	    int ret = left.cmp (o.left);
75	    if (ret) return ret;
76	    return right.cmp (o.right);
77	  }
78	
79	  inline bool sanitize (hb_sanitize_context_t *c) const
80	  {
81	    TRACE_SANITIZE (this);
82	    return_trace (c->check_struct (this));
83	  }
84	
85	  protected:
86	  GlyphID	left;
87	  GlyphID	right;
88	  FWORD		value;
89	  public:
90	  DEFINE_SIZE_STATIC (6);
91	};
