93	template <typename KernSubTableHeader>
94	struct KerxSubTableFormat0
95	{
96	  inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right) const
97	  {
98	    hb_glyph_pair_t pair = {left, right};
99	    int i = pairs.bsearch (pair);
100	    if (i == -1) return 0;
101	    return pairs[i].get_kerning ();
102	  }
103	
104	  inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right,
105				  hb_aat_apply_context_t *c) const
106	  {
107	    hb_glyph_pair_t pair = {left, right};
108	    int i = pairs.bsearch (pair);
109	    if (i == -1) return 0;
110	    int v = pairs[i].get_kerning ();
111	    return kerxTupleKern (v, header.tuple_count (), this, c);
112	  }
113	
114	  inline bool apply (hb_aat_apply_context_t *c) const
115	  {
116	    TRACE_APPLY (this);
117	
118	    if (!c->plan->requested_kerning)
119	      return false;
120	
121	    if (header.coverage & header.Backwards)
122	      return false;
123	
124	    accelerator_t accel (*this, c);
125	    hb_kern_machine_t<accelerator_t> machine (accel, header.coverage & header.CrossStream);
126	    machine.kern (c->font, c->buffer, c->plan->kern_mask);
127	
128	    return_trace (true);
129	  }
130	
131	  struct accelerator_t
132	  {
133	    const KerxSubTableFormat0 &table;
134	    hb_aat_apply_context_t *c;
135	
136	    inline accelerator_t (const KerxSubTableFormat0 &table_,
137				  hb_aat_apply_context_t *c_) :
138				    table (table_), c (c_) {}
139	
140	    inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right) const
141	    { return table.get_kerning (left, right, c); }
142	  };
143	
144	
145	  inline bool sanitize (hb_sanitize_context_t *c) const
146	  {
147	    TRACE_SANITIZE (this);
148	    return_trace (likely (pairs.sanitize (c)));
149	  }
150	
151	  protected:
152	  KernSubTableHeader	header;
153	  BinSearchArrayOf<KernPair, typename KernSubTableHeader::Types::HBUINT>
154				pairs;	/* Sorted kern records. */
155	  public:
156	  DEFINE_SIZE_ARRAY (KernSubTableHeader::static_size + 16, pairs);
157	};
