393	template <typename KernSubTableHeader>
394	struct KerxSubTableFormat2
395	{
396	  typedef typename KernSubTableHeader::Types Types;
397	  typedef typename Types::HBUINT HBUINT;
398	
399	  inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right,
400				  hb_aat_apply_context_t *c) const
401	  {
402	    unsigned int num_glyphs = c->sanitizer.get_num_glyphs ();
403	    unsigned int l = (this+leftClassTable).get_class (left, num_glyphs, 0);
404	    unsigned int r = (this+rightClassTable).get_class (right, num_glyphs, 0);
405	    unsigned int offset = l + r;
406	    const FWORD *v = &StructAtOffset<FWORD> (&(this+array), offset);
407	    if (unlikely (!v->sanitize (&c->sanitizer))) return 0;
408	    return kerxTupleKern (*v, header.tuple_count (), this, c);
409	  }
410	
411	  inline bool apply (hb_aat_apply_context_t *c) const
412	  {
413	    TRACE_APPLY (this);
414	
415	    if (!c->plan->requested_kerning)
416	      return false;
417	
418	    if (header.coverage & header.Backwards)
419	      return false;
420	
421	    accelerator_t accel (*this, c);
422	    hb_kern_machine_t<accelerator_t> machine (accel, header.coverage & header.CrossStream);
423	    machine.kern (c->font, c->buffer, c->plan->kern_mask);
424	
425	    return_trace (true);
426	  }
427	
428	  struct accelerator_t
429	  {
430	    const KerxSubTableFormat2 &table;
431	    hb_aat_apply_context_t *c;
432	
433	    inline accelerator_t (const KerxSubTableFormat2 &table_,
434				  hb_aat_apply_context_t *c_) :
435				    table (table_), c (c_) {}
436	
437	    inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right) const
438	    { return table.get_kerning (left, right, c); }
439	  };
440	
441	  inline bool sanitize (hb_sanitize_context_t *c) const
442	  {
443	    TRACE_SANITIZE (this);
444	    return_trace (likely (c->check_struct (this) &&
445				  leftClassTable.sanitize (c, this) &&
446				  rightClassTable.sanitize (c, this) &&
447				  c->check_range (this, array)));
448	  }
449	
450	  /* Note:
451	   * OT kern table specifies ClassTable as having 16-bit entries, whereas
452	   * AAT kern table specifies them as having 8bit entries.
453	   * I've not seen any fonts with this format in kern table.
454	   * We follow AAT. */
455	
456	  protected:
457	  KernSubTableHeader	header;
458	  HBUINT		rowWidth;	/* The width, in bytes, of a row in the table. */
459	  OffsetTo<typename Types::ClassType, HBUINT, false>
460				leftClassTable;	/* Offset from beginning of this subtable to
461						 * left-hand class table. */
462	  OffsetTo<typename Types::ClassType, HBUINT, false>
463				rightClassTable;/* Offset from beginning of this subtable to
464						 * right-hand class table. */
465	  OffsetTo<UnsizedArrayOf<FWORD>, HBUINT, false>
466				 array;		/* Offset from beginning of this subtable to
467						 * the start of the kerning array. */
468	  public:
469	  DEFINE_SIZE_STATIC (KernSubTableHeader::static_size + 4 * sizeof (HBUINT));
470	};
