472	template <typename KernSubTableHeader>
473	struct KerxSubTableFormat4
474	{
475	  typedef ExtendedTypes Types;
476	
477	  struct EntryData
478	  {
479	    HBUINT16	ankrActionIndex;/* Either 0xFFFF (for no action) or the index of
480					 * the action to perform. */
481	    public:
482	    DEFINE_SIZE_STATIC (2);
483	  };
484	
485	  struct driver_context_t
486	  {
487	    static const bool in_place = true;
488	    enum Flags
489	    {
490	      Mark		= 0x8000,	/* If set, remember this glyph as the marked glyph. */
491	      DontAdvance	= 0x4000,	/* If set, don't advance to the next glyph before
492						 * going to the new state. */
493	      Reserved		= 0x3FFF,	/* Not used; set to 0. */
494	    };
495	
496	    enum SubTableFlags
497	    {
498	      ActionType	= 0xC0000000,	/* A two-bit field containing the action type. */
499	      Unused		= 0x3F000000,	/* Unused - must be zero. */
500	      Offset		= 0x00FFFFFF,	/* Masks the offset in bytes from the beginning
501						 * of the subtable to the beginning of the control
502						 * point table. */
503	    };
504	
505	    inline driver_context_t (const KerxSubTableFormat4 *table,
506				     hb_aat_apply_context_t *c_) :
507		c (c_),
508		action_type ((table->flags & ActionType) >> 30),
509		ankrData ((HBUINT16 *) ((const char *) &table->machine + (table->flags & Offset))),
510		mark_set (false),
511		mark (0) {}
512	
513	    inline bool is_actionable (StateTableDriver<Types, EntryData> *driver HB_UNUSED,
514				       const Entry<EntryData> *entry)
515	    {
516	      return entry->data.ankrActionIndex != 0xFFFF;
517	    }
518	    inline bool transition (StateTableDriver<Types, EntryData> *driver,
519				    const Entry<EntryData> *entry)
520	    {
521	      hb_buffer_t *buffer = driver->buffer;
522	
523	      if (mark_set && entry->data.ankrActionIndex != 0xFFFF && buffer->idx < buffer->len)
524	      {
525		hb_glyph_position_t &o = buffer->cur_pos();
526		switch (action_type)
527		{
528		  case 0: /* Control Point Actions.*/
529		  {
530		    /* indexed into glyph outline. */
531		    const HBUINT16 *data = &ankrData[entry->data.ankrActionIndex];
532		    if (!c->sanitizer.check_array (data, 2))
533		      return false;
534		    HB_UNUSED unsigned int markControlPoint = *data++;
535		    HB_UNUSED unsigned int currControlPoint = *data++;
536		    hb_position_t markX = 0;
537		    hb_position_t markY = 0;
538		    hb_position_t currX = 0;
539		    hb_position_t currY = 0;
540		    if (!c->font->get_glyph_contour_point_for_origin (c->buffer->info[mark].codepoint,
541								      markControlPoint,
542								      HB_DIRECTION_LTR /*XXX*/,
543								      &markX, &markY) ||
544			!c->font->get_glyph_contour_point_for_origin (c->buffer->cur ().codepoint,
545								      currControlPoint,
546								      HB_DIRECTION_LTR /*XXX*/,
547								      &currX, &currY))
548		      return true; /* True, such that the machine continues. */
549	
550		    o.x_offset = markX - currX;
551		    o.y_offset = markY - currY;
552		  }
553		  break;
554	
555		  case 1: /* Anchor Point Actions. */
556		  {
557		   /* Indexed into 'ankr' table. */
558		    const HBUINT16 *data = &ankrData[entry->data.ankrActionIndex];
559		    if (!c->sanitizer.check_array (data, 2))
560		      return false;
561		    unsigned int markAnchorPoint = *data++;
562		    unsigned int currAnchorPoint = *data++;
563		    const Anchor markAnchor = c->ankr_table->get_anchor (c->buffer->info[mark].codepoint,
564									 markAnchorPoint,
565									 c->sanitizer.get_num_glyphs (),
566									 c->ankr_end);
567		    const Anchor currAnchor = c->ankr_table->get_anchor (c->buffer->cur ().codepoint,
568									 currAnchorPoint,
569									 c->sanitizer.get_num_glyphs (),
570									 c->ankr_end);
571	
572		    o.x_offset = c->font->em_scale_x (markAnchor.xCoordinate) - c->font->em_scale_x (currAnchor.xCoordinate);
573		    o.y_offset = c->font->em_scale_y (markAnchor.yCoordinate) - c->font->em_scale_y (currAnchor.yCoordinate);
574		  }
575		  break;
576	
577		  case 2: /* Control Point Coordinate Actions. */
578		  {
579		    const FWORD *data = (const FWORD *) &ankrData[entry->data.ankrActionIndex];
580		    if (!c->sanitizer.check_array (data, 4))
581		      return false;
582		    int markX = *data++;
583		    int markY = *data++;
584		    int currX = *data++;
585		    int currY = *data++;
586	
587		    o.x_offset = c->font->em_scale_x (markX) - c->font->em_scale_x (currX);
588		    o.y_offset = c->font->em_scale_y (markY) - c->font->em_scale_y (currY);
589		  }
590		  break;
591		}
592		o.attach_type() = ATTACH_TYPE_MARK;
593		o.attach_chain() = (int) mark - (int) buffer->idx;
594		buffer->scratch_flags |= HB_BUFFER_SCRATCH_FLAG_HAS_GPOS_ATTACHMENT;
595	      }
596	
597	      if (entry->flags & Mark)
598	      {
599		mark_set = true;
600		mark = buffer->idx;
601	      }
602	
603	      return true;
604	    }
605	
606	    private:
607	    hb_aat_apply_context_t *c;
608	    unsigned int action_type;
609	    const HBUINT16 *ankrData;
610	    bool mark_set;
611	    unsigned int mark;
612	  };
613	
614	  inline bool apply (hb_aat_apply_context_t *c) const
615	  {
616	    TRACE_APPLY (this);
617	
618	    driver_context_t dc (this, c);
619	
620	    StateTableDriver<Types, EntryData> driver (machine, c->buffer, c->font->face);
621	    driver.drive (&dc);
622	
623	    return_trace (true);
624	  }
625	
626	  inline bool sanitize (hb_sanitize_context_t *c) const
627	  {
628	    TRACE_SANITIZE (this);
629	    /* The rest of array sanitizations are done at run-time. */
630	    return_trace (likely (c->check_struct (this) &&
631				  machine.sanitize (c)));
632	  }
633	
634	  protected:
635	  KernSubTableHeader		header;
636	  StateTable<Types, EntryData>	machine;
637	  HBUINT32			flags;
638	  public:
639	  DEFINE_SIZE_STATIC (KernSubTableHeader::static_size + 20);
640	};
641	
642	template <typename KernSubTableHeader>
643	struct KerxSubTableFormat6
644	{
645	  enum Flags
646	  {
647	    ValuesAreLong	= 0x00000001,
648	  };
649	
650	  inline bool is_long (void) const { return flags & ValuesAreLong; }
651	
652	  inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right,
653				  hb_aat_apply_context_t *c) const
654	  {
655	    unsigned int num_glyphs = c->sanitizer.get_num_glyphs ();
656	    if (is_long ())
657	    {
658	      const typename U::Long &t = u.l;
659	      unsigned int l = (this+t.rowIndexTable).get_value_or_null (left, num_glyphs);
660	      unsigned int r = (this+t.columnIndexTable).get_value_or_null (right, num_glyphs);
661	      unsigned int offset = l + r;
662	      if (unlikely (offset < l)) return 0; /* Addition overflow. */
663	      if (unlikely (hb_unsigned_mul_overflows (offset, sizeof (FWORD32)))) return 0;
664	      const FWORD32 *v = &StructAtOffset<FWORD32> (&(this+t.array), offset * sizeof (FWORD32));
665	      if (unlikely (!v->sanitize (&c->sanitizer))) return 0;
666	      return kerxTupleKern (*v, header.tuple_count (), &(this+vector), c);
667	    }
668	    else
669	    {
670	      const typename U::Short &t = u.s;
671	      unsigned int l = (this+t.rowIndexTable).get_value_or_null (left, num_glyphs);
672	      unsigned int r = (this+t.columnIndexTable).get_value_or_null (right, num_glyphs);
673	      unsigned int offset = l + r;
674	      const FWORD *v = &StructAtOffset<FWORD> (&(this+t.array), offset * sizeof (FWORD));
675	      if (unlikely (!v->sanitize (&c->sanitizer))) return 0;
676	      return kerxTupleKern (*v, header.tuple_count (), &(this+vector), c);
677	    }
678	  }
679	
680	  inline bool apply (hb_aat_apply_context_t *c) const
681	  {
682	    TRACE_APPLY (this);
683	
684	    if (!c->plan->requested_kerning)
685	      return false;
686	
687	    if (header.coverage & header.Backwards)
688	      return false;
689	
690	    accelerator_t accel (*this, c);
691	    hb_kern_machine_t<accelerator_t> machine (accel, header.coverage & header.CrossStream);
692	    machine.kern (c->font, c->buffer, c->plan->kern_mask);
693	
694	    return_trace (true);
695	  }
696	
697	  inline bool sanitize (hb_sanitize_context_t *c) const
698	  {
699	    TRACE_SANITIZE (this);
700	    return_trace (likely (c->check_struct (this) &&
701				  (is_long () ?
702				   (
703				     u.l.rowIndexTable.sanitize (c, this) &&
704				     u.l.columnIndexTable.sanitize (c, this) &&
705				     c->check_range (this, u.l.array)
706				   ) : (
707				     u.s.rowIndexTable.sanitize (c, this) &&
708				     u.s.columnIndexTable.sanitize (c, this) &&
709				     c->check_range (this, u.s.array)
710				   )) &&
711				  (header.tuple_count () == 0 ||
712				   c->check_range (this, vector))));
713	  }
714	
715	  struct accelerator_t
716	  {
717	    const KerxSubTableFormat6 &table;
718	    hb_aat_apply_context_t *c;
719	
720	    inline accelerator_t (const KerxSubTableFormat6 &table_,
721				  hb_aat_apply_context_t *c_) :
722				    table (table_), c (c_) {}
723	
724	    inline int get_kerning (hb_codepoint_t left, hb_codepoint_t right) const
725	    { return table.get_kerning (left, right, c); }
726	  };
727	
728	  protected:
729	  KernSubTableHeader		header;
730	  HBUINT32			flags;
731	  HBUINT16			rowCount;
732	  HBUINT16			columnCount;
733	  union U
734	  {
735	    struct Long
736	    {
737	      LOffsetTo<Lookup<HBUINT32>, false>	rowIndexTable;
738	      LOffsetTo<Lookup<HBUINT32>, false>	columnIndexTable;
739	      LOffsetTo<UnsizedArrayOf<FWORD32>, false>	array;
740	    } l;
741	    struct Short
742	    {
743	      LOffsetTo<Lookup<HBUINT16>, false>	rowIndexTable;
744	      LOffsetTo<Lookup<HBUINT16>, false>	columnIndexTable;
745	      LOffsetTo<UnsizedArrayOf<FWORD>, false>	array;
746	    } s;
747	  } u;
748	  LOffsetTo<UnsizedArrayOf<FWORD>, false>	vector;
749	  public:
750	  DEFINE_SIZE_STATIC (KernSubTableHeader::static_size + 24);
751	};
752	
753	
754	struct KerxSubTableHeader
755	{
756	  typedef ExtendedTypes Types;
757	
758	  inline unsigned int tuple_count (void) const { return tupleCount; }
759	  inline bool is_horizontal (void) const { return !(coverage & Vertical); }
760	
761	  enum Coverage
762	  {
763	    Vertical	= 0x80000000u,	/* Set if table has vertical kerning values. */
764	    CrossStream	= 0x40000000u,	/* Set if table has cross-stream kerning values. */
765	    Variation	= 0x20000000u,	/* Set if table has variation kerning values. */
766	    Backwards	= 0x10000000u,	/* If clear, process the glyphs forwards, that
767					 * is, from first to last in the glyph stream.
768					 * If we, process them from last to first.
769					 * This flag only applies to state-table based
770					 * 'kerx' subtables (types 1 and 4). */
771	    Reserved	= 0x0FFFFF00u,	/* Reserved, set to zero. */
772	    SubtableType= 0x000000FFu,	/* Subtable type. */
773	  };
774	
775	  inline bool sanitize (hb_sanitize_context_t *c) const
776	  {
777	    TRACE_SANITIZE (this);
778	    return_trace (likely (c->check_struct (this)));
779	  }
780	
781	  public:
782	  HBUINT32	length;
783	  HBUINT32	coverage;
784	  HBUINT32	tupleCount;
785	  public:
786	  DEFINE_SIZE_STATIC (12);
787	};
788	
789	struct KerxSubTable
790	{
791	  friend struct kerx;
792	
793	  inline unsigned int get_size (void) const { return u.header.length; }
794	  inline unsigned int get_type (void) const { return u.header.coverage & u.header.SubtableType; }
795	
796	  template <typename context_t>
797	  inline typename context_t::return_t dispatch (context_t *c) const
798	  {
799	    unsigned int subtable_type = get_type ();
800	    TRACE_DISPATCH (this, subtable_type);
801	    switch (subtable_type) {
802	    case 0:	return_trace (c->dispatch (u.format0));
803	    case 1:	return_trace (c->dispatch (u.format1));
804	    case 2:	return_trace (c->dispatch (u.format2));
805	    case 4:	return_trace (c->dispatch (u.format4));
806	    case 6:	return_trace (c->dispatch (u.format6));
807	    default:	return_trace (c->default_return_value ());
808	    }
809	  }
810	
811	  inline bool sanitize (hb_sanitize_context_t *c) const
812	  {
813	    TRACE_SANITIZE (this);
814	    if (!u.header.sanitize (c) ||
815		!c->check_range (this, u.header.length))
816	      return_trace (false);
817	
818	    return_trace (dispatch (c));
819	  }
820	
821	  public:
822	  union {
823	  KerxSubTableHeader				header;
824	  KerxSubTableFormat0<KerxSubTableHeader>	format0;
825	  KerxSubTableFormat1<KerxSubTableHeader>	format1;
826	  KerxSubTableFormat2<KerxSubTableHeader>	format2;
827	  KerxSubTableFormat4<KerxSubTableHeader>	format4;
828	  KerxSubTableFormat6<KerxSubTableHeader>	format6;
829	  } u;
830	  public:
831	  DEFINE_SIZE_MIN (12);
832	};
833	
834	
835	/*
836	 * The 'kerx' Table
837	 */
838	
839	template <typename T>
840	struct KerxTable
841	{
842	  /* https://en.wikipedia.org/wiki/Curiously_recurring_template_pattern */
843	  inline const T* thiz (void) const { return static_cast<const T *> (this); }
844	
845	  inline bool has_cross_stream (void) const
846	  {
847	    typedef typename T::SubTable SubTable;
848	
849	    const SubTable *st = &thiz()->firstSubTable;
850	    unsigned int count = thiz()->tableCount;
851	    for (unsigned int i = 0; i < count; i++)
852	    {
853	      if (st->u.header.coverage & st->u.header.CrossStream)
854	        return true;
855	      st = &StructAfter<SubTable> (*st);
856	    }
857	    return false;
858	  }
859	
860	  inline int get_h_kerning (hb_codepoint_t left, hb_codepoint_t right) const
861	  {
862	    typedef typename T::SubTable SubTable;
863	
864	    int v = 0;
865	    const SubTable *st = &thiz()->firstSubTable;
866	    unsigned int count = thiz()->tableCount;
867	    for (unsigned int i = 0; i < count; i++)
868	    {
869	      if ((st->u.header.coverage & (st->u.header.Variation | st->u.header.CrossStream)) ||
870		  !st->u.header.is_horizontal ())
871	        continue;
872	      v += st->get_kerning (left, right);
873	      st = &StructAfter<SubTable> (*st);
874	    }
875	    return v;
876	  }
877	
878	  inline bool apply (AAT::hb_aat_apply_context_t *c) const
879	  {
880	    typedef typename T::SubTable SubTable;
881	
882	    bool ret = false;
883	    bool seenCrossStream = false;
884	    c->set_lookup_index (0);
885	    const SubTable *st = &thiz()->firstSubTable;
886	    unsigned int count = thiz()->tableCount;
887	    for (unsigned int i = 0; i < count; i++)
888	    {
889	      bool reverse;
890	
891	      if (!T::Types::extended && (st->u.header.coverage & st->u.header.Variation))
892	        goto skip;
893	
894	      if (HB_DIRECTION_IS_HORIZONTAL (c->buffer->props.direction) != st->u.header.is_horizontal ())
895		goto skip;
896	
897	      reverse = bool (st->u.header.coverage & st->u.header.Backwards) !=
898			HB_DIRECTION_IS_BACKWARD (c->buffer->props.direction);
899	
900	      if (!c->buffer->message (c->font, "start %c%c%c%c subtable %d", HB_UNTAG (thiz()->tableTag), c->lookup_index))
901		goto skip;
902	
903	      if (!seenCrossStream &&
904		  (st->u.header.coverage & st->u.header.CrossStream))
905	      {
906	        /* Attach all glyphs into a chain. */
907	        seenCrossStream = true;
908		hb_glyph_position_t *pos = c->buffer->pos;
909		unsigned int count = c->buffer->len;
910		for (unsigned int i = 0; i < count; i++)
911		{
912		  pos[i].attach_type() = ATTACH_TYPE_CURSIVE;
913		  pos[i].attach_chain() = HB_DIRECTION_IS_FORWARD (c->buffer->props.direction) ? -1 : +1;
914		  /* We intentionally don't set HB_BUFFER_SCRATCH_FLAG_HAS_GPOS_ATTACHMENT,
915		   * since there needs to be a non-zero attachment for post-positioning to
916		   * be needed. */
917		}
918	      }
919	
920	      if (reverse)
921		c->buffer->reverse ();
922	
923	      c->sanitizer.set_object (*st);
924	
925	      ret |= st->dispatch (c);
926	
927	      if (reverse)
928		c->buffer->reverse ();
929	
930	      (void) c->buffer->message (c->font, "end %c%c%c%c subtable %d", HB_UNTAG (thiz()->tableTag), c->lookup_index);
931	
932	    skip:
933	      st = &StructAfter<SubTable> (*st);
934	      c->set_lookup_index (c->lookup_index + 1);
935	    }
936	
937	    return ret;
938	  }
939	
940	  inline bool sanitize (hb_sanitize_context_t *c) const
941	  {
942	    TRACE_SANITIZE (this);
943	    if (unlikely (!thiz()->version.sanitize (c) ||
944			  thiz()->version < T::minVersion ||
945			  !thiz()->tableCount.sanitize (c)))
946	      return_trace (false);
947	
948	    typedef typename T::SubTable SubTable;
949	
950	    const SubTable *st = &thiz()->firstSubTable;
951	    unsigned int count = thiz()->tableCount;
952	    for (unsigned int i = 0; i < count; i++)
953	    {
954	      if (unlikely (!st->sanitize (c)))
955		return_trace (false);
956	      st = &StructAfter<SubTable> (*st);
957	    }
958	
959	    return_trace (true);
960	  }
961	};
962	
963	struct kerx : KerxTable<kerx>
964	{
965	  friend struct KerxTable<kerx>;
966	
967	  static const hb_tag_t tableTag = HB_AAT_TAG_kerx;
968	  static const uint16_t minVersion = 2;
969	
970	  typedef KerxSubTableHeader SubTableHeader;
971	  typedef SubTableHeader::Types Types;
972	  typedef KerxSubTable SubTable;
973	
974	  inline bool has_data (void) const { return version; }
975	
976	  protected:
977	  HBUINT16	version;	/* The version number of the extended kerning table
978					 * (currently 2, 3, or 4). */
979	  HBUINT16	unused;		/* Set to 0. */
980	  HBUINT32	tableCount;	/* The number of subtables included in the extended kerning
981					 * table. */
982	  SubTable	firstSubTable;	/* Subtables. */
983	/*subtableGlyphCoverageArray*/	/* Only if version >= 3. We don't use. */
984	
985	  public:
986	  DEFINE_SIZE_MIN (8);
987	};
988	
989	
990	} /* namespace AAT */
991	
992	
993	#endif /* HB_AAT_LAYOUT_KERX_TABLE_HH */
